SELECT order_items.id, order_items.product_id, order_items.unit_price, orders.amount, orders.customer_id, products.supplier_id, products.category, LEAST(orders.discount, orders.amount) AS least_discount_amount FROM order_items INNER JOIN orders ON order_items.order_id = orders.id LEFT OUTER JOIN products ON order_items.product_id = products.id WHERE LENGTH(products.product_name) >= 10 AND orders.customer_id IN (21, 23, 33);
